import torch


def run(x, size, fill_value, dtype=None):
    if isinstance(fill_value, str):
        fill_value = float(fill_value)
    if dtype is not None:
        return x.new_full(size, fill_value, dtype=getattr(torch, dtype))
    return x.new_full(size, fill_value)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch

    ref = ref_outputs[0].detach().to("cpu")
    sol = sol_outputs[0].detach().to("cpu")
    if ref.shape != sol.shape:
        return {"passed": False, "message": f"shape {sol.shape} vs {ref.shape}", "metrics": {}}
    if ref.dtype != sol.dtype:
        return {"passed": False, "message": f"dtype {sol.dtype} vs {ref.dtype}", "metrics": {}}
    r = ref.to(torch.float64)
    s = sol.to(torch.float64)
    both_nan = torch.isnan(r) & torch.isnan(s)
    eq = r == s
    ok = bool((eq | both_nan).all().item())
    return {"passed": ok, "message": "", "metrics": {}}
